import{_ as s,a0 as m,w as o,s as r,I as n,x as i,a1 as t,A as l,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"愛的初體驗 —— Semplice Linux 5 | LCTT x X-CMD","titleTemplate":false,"description":"愛的初體驗 —— Semplice Linux 5 | LCTT (201310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"愛的初體驗 —— Semplice Linux 5 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"愛的初體驗 —— Semplice Linux 5 | LCTT (201310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201310/First impressions of Semplice Linux 5","title":"愛的初體驗 —— Semplice Linux 5","tag":"201310","desc":""},"relativePath":"201310/First impressions of Semplice Linux 5.md","filePath":"[post].md"}'),S={name:"201310/First impressions of Semplice Linux 5.md"};function u(x,e,d,L,c,b){const p=m("Link");return o(),r("div",null,[e[15]||(e[15]=n("h1",{id:"愛的初體驗-——-semplice-linux-5",tabindex:"-1"},[i("愛的初體驗 —— Semplice Linux 5 "),n("a",{class:"header-anchor",href:"#愛的初體驗-——-semplice-linux-5","aria-label":"Permalink to “愛的初體驗 —— Semplice Linux 5”"},"​")],-1)),n("p",null,[t(p,{href:"http://distrowatch.com/semplice"},{default:l(()=>[...e[0]||(e[0]=[i("Semplice",-1)])]),_:1}),e[2]||(e[2]=i(" 是一個基於Debian GNU/Linux項目的Linux發行版，基於Debian不穩定分支構建。開發者使用不穩定倉庫中的軟件包，並通過一個自定義圖形界面安裝程序將這些軟件包加以整合。",-1)),t(p,{href:"http://semplice-linux.org/"},{default:l(()=>[...e[1]||(e[1]=[i("項目官網",-1)])]),_:1}),e[3]||(e[3]=i("介紹説該Semplice不但支持加密LVM卷，而且整合了Openbox窗口管理器，並始終專注於更加快速、輕便的資源，“簡約不簡單”。該發行版目前支持32位、64位ISO鏡像下載，體積大概620MB左右。",-1))]),e[16]||(e[16]=a('<p>從LiveCD啓動後，可以看到一個圖形界面窗口，它包括3個標籤頁，分別用來設置鍵盤佈局、系統語言和所在時區。確認上述設置正確無誤後，關閉窗口，就可以看到Openbox界面那明亮的藍色背景了。在顯示器底部我們發現了一個任務切換界面和一個系統托盤。點擊鼠標右鍵可以呼出程序菜單，菜單頂部其中一項就是系統安裝程序的入口。</p><p><img src="http://distrowatch.com/images/screenshots/semplice-5-web.png" alt=""> Semplice Linux 5 —— 訪問項目官網（截圖大小398KB，分辨率1280x960）</p><p>Semplice的系統安裝程序同樣為圖形化界面。程序界面友好，引導步驟也比較清晰。首先，程序會讓我們確認首選的語言、鍵盤和時區，然後會詢問是否要檢測安裝程序有無更新，我很負責任的選擇了“是”，它竟然真的聯網找到了自己的新版本，於是，我又下載更新，安裝程序自動重啓執行更新（……作者你是話嘮嗎？）接下來，程序要求我們創建一個用户賬户，同時，提供了是否激活root賬户的選項。Semplice默認是將第一個用户賬户作為sudo管理員同時禁用root賬户的。儘管如此，我們仍然可以激活root賬户再給它設置一個密碼。然後，來到磁盤分區界面，程序自動幫我們完成了一套分區建議，當然，你也可以選擇自己手動分區。</p><p>這裏我發現手動分區會有點尷尬，主要是由於屏幕的佈局。另外，我還發現當我嘗試建立LVM卷的時候，程序卻並不允許，一個對話框會讓我輸入卷的名稱，但是它的“OK”按鈕卻無法點擊，着實讓人納悶。文件系統還是傳統的幾個，ext2/3/4和ReiserFS，分區之後，它會詢問是否要安裝GRUB，以上步驟都完成後，最後一步需要我們選擇是否開啓一些功能與服務，然後就開始正式安裝了。安裝的同時，安裝程序會詢問我們是否需要一些額外的工具，例如藍牙支持、打印機、生產套件、桌面特效、Web應用以及專有軟件包，如果你選擇需要，程序就會自動將它們拷貝至本地磁盤。整個安裝過程只需要幾分鐘，安裝完畢後，需要重啓電腦。</p><p>除了基本所需的文本編輯器、計算器、圖像瀏覽、文件管理與檔案管理外，Semplice Linux發行版還預裝了很多有用的軟件，例如Chromium瀏覽器、Claws Mail郵件客户端、XChat IRC以及Pidgin等聊天軟件。另外，下載軟件有gFTP和uGet，文檔處理有GNU Paint、AbiWord、Gnumeric，娛樂播放有MPlayer、Exaile，刻錄工具有xfburn，遊戲子菜單下還有一個Tetris。</p><p>程序菜單中還有許多有用的配置工具，通過這些工具用户可以對網絡設置、系統服務、用户賬户等進行輕鬆配置。同時，系統還提供了程序對Openbox窗口管理器進行管理。在Web應用部分，用户可以以最簡方式打開一個web瀏覽器，用來訪問Twitter和Facebook。系統還提供了前往Semplice項目官網的快捷方式。通過深度挖掘，我發現Semplice具有一整套完備的多媒體編碼解碼器和Adobe Flash插件。系統默認採用的是安全shell服務(OpenSSH)。我還發現系統預裝了GNU編譯工具集。而在內核方面，Semplice採用3.10版本，能夠保證以上各個工具軟件正常運行。</p><p><img src="http://distrowatch.com/images/screenshots/semplice-5-apps.png" alt=""> Semplice Linux 5 —— 運行各種桌面程序（截圖大小241KB，分辨率1280x960）</p><p>使用Semplice工作的過程中我也遇到了一些小問題。比如，當我在虛擬終端運行“top”進程監視器的時候，窗口頂端的系統統計信息會無故消失，稍微折騰了一番，我發現原來是因為虛擬終端的顏色配置導致了文字不可見。但是當我修改主題顏色一段時間以後，下一次我再打開一個終端，主題顏色又回到了以前的默認值。如此反覆，每次關閉終端後，我的設置總會丟失。丟失設置的另一個表現是，之前安裝過程中配置好的一些服務也失效了，包括藍牙、打印機支持、Web應用和其他一些項目。</p><p>當時我告訴安裝程序不要安裝藍牙和打印軟件，但是後來我在服務管理器裏還是看到了它倆在活蹦亂跳地運行着。</p><p>第三個奇怪的問題是，當我嘗試連接SSH服務的時候，總是被告知連接丟失被重置，很快我發現問題原因是由於系統根本就木有生成OpenSSH所需的主機密鑰。當我手動生成這些密鑰後，就可以使用安全Shell服務了。</p><p>新立德（Synaptic）作為通用軟件包管理器負責Semplice發行版軟件包的管理與更新。通常功能強大的軟件包管理器難以兼顧漂亮的外觀，但新立德做到了。它允許用户創建一系列行為動作，並且執行迅速，執行的同時還能顯示詳細的細節信息。Linux發行版一般會從一些不同的軟件倉庫獲取軟件，Semplice默認是從Debian的不穩定分支倉庫以及其他一些Semplice的自定義倉庫中獲取。當我初次安裝好Semplice的時候，就有137個更新等着我下載安裝，體積總共達到了135MB。一週下來，我總共安裝了超過200個更新，體積超過200MB。Semplice不愧是基於Debian的不穩定分支，不但更新速度超快，而且採用的都是快速更新的前沿軟件包。</p><p><img src="http://distrowatch.com/images/screenshots/semplice-5-admin.png" alt=""> Semplice Linux 5 —— 管理軟件包與服務（截圖大小299KB，分辨率1280x960）</p><p>我嘗試在我的台式機上運行Semplice Linux（CPU雙核2.8GHz，內存6G，Radeon顯卡，Realtek網卡），然而不管我如何修改內核參數，都無法在實體機上運行，但是在VirtualBox虛擬機上卻運行的很好。在VirtualBox裏，Semplice啓動快速，反應靈敏而且整個測試過程都非常穩定。Semplice所需的配置內存相當低，只需要130MB。</p><p>整個Semplice體驗過程一個詞概括：還行（Okay）。這既不是認可也不是否定。總體上講，Semplice表現還是不錯的，它提供了很多優秀的軟件，而且我認為它的安裝程序比Debian的要漂亮，至少在桌面系統上如此。Semplice的管理員工具很實用，除此以外，通過訪問Debian的軟件倉庫，它還提供了海量軟件包供普通用户選用。該發行版緊跟前沿，不喜歡總是下載更新的用户可能會比較介意，但是同時這也意味着它為我們提供了不斷嘗試新鮮事物的機會。以上是好的方面。不好的方面，在我測試的過程中也出現了一些問題，例如，安裝程序並未採納我對系統服務的一些配置，我也無法使用加密LVM卷。</p><p>還有其他一些小問題，像虛擬終端丟失設置等等。另外，我始終禁不住會想，Semplice為何不用LXDE代替Openbox作為圖形接口呢？我並不是對Openbox有什麼偏見，但LXDE可以提供更美觀、常見的圖形接口，特別是對於新手用户，就好像在家裏面對自己熟悉的環境一樣。另一個問題是，Semplice無法在我的實體機上運行，也許我的情況是個案，反過來可能別人運行不了的系統我的電腦卻可以運行，我也並不想以此對Semplice吹毛求疵，但是，其他Debian類的系統例如Ubuntu和Debian版的Mint，都可以在我的機子上流暢運行，因此，當發現Semplice運行不了時候，我當時還是有些驚訝的。最後一個問題，OpenSSH運行時，沒有自動生成主機密鑰，導致安全Shell連接丟失，雖説手動生成新的主機密鑰只是小事一樁，但如果它啓動的時候就能自動完成這些工作豈不是更好。</p><p>總結一下，對於Semplice，我“愛的初體驗”看起來還是比較美好的，它為簡約Debian做出了不少改進（至少對於台式機/筆記本用户），默認所選擇的軟件也都不錯。儘管如此，它還是有一些毛邊兒略顯粗糙。也許這不算什麼，因為沒有什麼能嚇住我們Linux系統測試員，但我還是衷心希望不久的將來，Semplice的新版本能改善上面那些問題。</p><hr>',17)),n("p",null,[e[5]||(e[5]=i("via: ",-1)),t(p,{href:"http://distrowatch.com/weekly.php?issue=20131007"},{default:l(()=>[...e[4]||(e[4]=[i("http://distrowatch.com/weekly.php?issue=20131007",-1)])]),_:1})]),n("p",null,[e[8]||(e[8]=i("本文由 ",-1)),t(p,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[6]||(e[6]=[i("LCTT",-1)])]),_:1}),e[9]||(e[9]=i(" 原創翻譯，",-1)),t(p,{href:"http://linux.cn/"},{default:l(()=>[...e[7]||(e[7]=[i("Linux中國",-1)])]),_:1}),e[10]||(e[10]=i(" 榮譽推出",-1))]),n("p",null,[e[13]||(e[13]=i("譯者：",-1)),t(p,{href:"https://github.com/tinyeyeser"},{default:l(()=>[...e[11]||(e[11]=[i("tinyeyeser",-1)])]),_:1}),e[14]||(e[14]=i(" 校對：",-1)),t(p,{href:"https://github.com/wxy"},{default:l(()=>[...e[12]||(e[12]=[i("wxy",-1)])]),_:1})])])}const g=s(S,[["render",u]]);export{C as __pageData,g as default};
